/**
 * hermes-office v5.0 "PERSIS GITHUB" — pixel office pane for the Hermes desktop app,
 * a faithful re-creation of paulrobello/claude-office (MIT) visuals:
 * dark slate building view (roof/floors/lobby/foundation), and per-floor
 * 1280x1024 pixel offices with real claude-office furniture sprites.
 *
 * What the pane shows:
 *  - v3.3 ONE-SCROLLER (default & only view): every profile's office
 *    interior rendered inline in a single scroll — wall strip, floor
 *    band, boss corner (rug + desk + monitor + crowned pixel boss),
 *    workstation slots (desk + monitor + chair + pixel employee, all
 *    bottom-anchored to the floor baseline), plant / cooler / printer
 *    props. Command center + lobby are inline bands, no click gates.
 *  - CLICK boss nameplate or employee -> host.openSession() to open
 *    that bot's chat directly (SDK: openSession(storedSessionId,
 *    { profile })).
 *
 * Data: profiles.list (include_sessions), session.active_list,
 * subagent.list (DEFAULT PROFILE ONLY — isolation by design; foreign
 * profiles render from their profiles.list snapshot), subagent.tail
 * (only for the selected subagent popover), host.state atoms.
 *
 * Sprites: original claude-office PNGs (MIT), downsampled and embedded
 * as data-URIs — self-contained single file, no assets to fetch.
 * Characters are pure SVG capsules (same geometry as claude-office's
 * CommandCenterPeer/BossSprite). No canvas, no rAF: CSS transitions
 * drive the walking.
 *
 * Plain ESM, no JSX syntax — jsx()/jsxs() from 'react/jsx-runtime'.
 */

import { jsx, jsxs } from 'react/jsx-runtime';
import { useCallback, useEffect, useMemo, useRef, useState } from 'react';
import {
  host,
  useValue,
  usePluginI18n,
  useQuery,
  useQueryClient,
  StatusDot,
  EmptyState,
  GlyphSpinner,
  cn,
  haptic,
} from '@hermes/plugin-sdk';

/* ------------------------------------------------------------------ */
/* Constants                                                           */
/* ------------------------------------------------------------------ */

const PLUGIN_ID = 'hermes-office';

/* Building title in the pane header. Rename it to your own tower. */
const TOWER_NAME = 'Hermes Tower';

const POLL_FAST = 2000;
const POLL_SLOW = 8000;

const TERMINAL = new Set(['completed', 'failed', 'error', 'timeout', 'interrupted']);
const FAILISH = new Set(['failed', 'error', 'timeout', 'interrupted']);
/* v4.0: WORKING_ST removed — profiles.list rows carry no status field (dead code) */

function rpc(method, params, fallback) {
  return host.request(method, params || {}).catch((err) => {
    if (fallback !== undefined) return fallback;
    throw err;
  });
}

function stubAtom(value) {
  return {
    subscribe() {
      return () => {};
    },
    get() {
      return value;
    },
  };
}

const busyAtom = (host && host.state && host.state.busyBySession) || stubAtom(undefined);
const focusAtom = (host && host.state && host.state.focusedSessionId) || stubAtom(null);
const usageAtom = (host && host.state && host.state.focusedUsage) || stubAtom(null);

