/* ------------------------------------------------------------------ */
/* Small utilities                                                     */
/* ------------------------------------------------------------------ */

function parseColor(c) {
  if (!c) return null;
  if (typeof c === 'number') {
    return { r: (c >> 16) & 255, g: (c >> 8) & 255, b: c & 255 };
  }
  const s = String(c).trim();
  let m = s.match(/^#([0-9a-f]{3})$/i);
  if (m) {
    return { r: parseInt(m[1][0] + m[1][0], 16), g: parseInt(m[1][1] + m[1][1], 16), b: parseInt(m[1][2] + m[1][2], 16) };
  }
  m = s.match(/^#([0-9a-f]{6})$/i);
  if (m) {
    return { r: parseInt(s.slice(1, 3), 16), g: parseInt(s.slice(3, 5), 16), b: parseInt(s.slice(5, 7), 16) };
  }
  m = s.match(/^rgba?\(([^)]+)\)$/i);
  if (m) {
    const p = m[1].split(/[,/\s]+/).filter(Boolean).map(Number);
    if (p.length >= 3) return { r: p[0] | 0, g: p[1] | 0, b: p[2] | 0 };
  }
  return null;
}

function clamp(v, a, b) {
  return v < a ? a : v > b ? b : v;
}

function mix(a, b, t) {
  return { r: clamp(Math.round(a.r + (b.r - a.r) * t), 0, 255), g: clamp(Math.round(a.g + (b.g - a.g) * t), 0, 255), b: clamp(Math.round(a.b + (b.b - a.b) * t), 0, 255) };
}

function toHsl(c) {
  const r = c.r / 255, g = c.g / 255, b = c.b / 255;
  const max = Math.max(r, g, b), min = Math.min(r, g, b);
  let h = 0;
  const l = (max + min) / 2;
  const d = max - min;
  const s = d === 0 ? 0 : d / (1 - Math.abs(2 * l - 1));
  if (d !== 0) {
    if (max === r) h = 60 * (((g - b) / d) % 6);
    else if (max === g) h = 60 * ((b - r) / d + 2);
    else h = 60 * ((r - g) / d + 4);
  }
  if (h < 0) h += 360;
  return { h, s, l };
}

function hsl(h, s, l) {
  const f = (n) => {
    const k = (n + h / 30) % 12;
    const a = s * Math.min(l, 1 - l);
    const v = l - a * Math.max(-1, Math.min(k - 3, Math.min(9 - k, 1)));
    return Math.round(255 * v);
  };
  return { r: f(0), g: f(8), b: f(4) };
}

function hashHue(s) {
  let h = 2169508751;
  s = String(s || '');
  for (let i = 0; i < s.length; i++) {
    h = Math.imul(h ^ s.charCodeAt(i), 16777619);
  }
  return Math.abs(h) % 360;
}

function fmtAgo(sec) {
  if (sec == null || !isFinite(sec)) return '—';
  if (sec < 45) return '<1m';
  if (sec < 5400) return Math.round(sec / 60) + 'm';
  if (sec < 129600) return Math.round(sec / 3600) + 'h';
  return Math.round(sec / 86400) + 'd';
}

function fmtDur(sec) {
  const m = Math.floor(sec / 60);
  const h = Math.floor(m / 60);
  if (h > 0) return h + 'h' + String(m % 60).padStart(2, '0');
  return m + ':' + String(sec % 60).padStart(2, '0');
}

function accentHue(accent) {
  /* hex #rrggbb -> approximate hue for pixel-shirt tint */
  try {
    const m = /^#([0-9a-f]{6})$/i.exec(String(accent));
    if (!m) return 200;
    const v = parseInt(m[1], 16);
    const r = ((v >> 16) & 255) / 255, g = ((v >> 8) & 255) / 255, b = (v & 255) / 255;
    const mx = Math.max(r, g, b), mn = Math.min(r, g, b);
    if (mx === mn) return 200;
    const d = mx - mn;
    let h;
    if (mx === r) h = ((g - b) / d) % 6;
    else if (mx === g) h = (b - r) / d + 2;
    else h = (r - g) / d + 4;
    return Math.round(((h * 60) + 360) % 360);
  } catch (e) { return 200; }
}

function accentFromHue(hue) {
  const c = hsl(hue, 0.62, 0.62);
  return '#' + [c.r, c.g, c.b].map((x) => x.toString(16).padStart(2, '0')).join('');
}

function assignBotHues(bots) {
  const used = new Set();
  for (const b of bots) {
    let hue = hashHue(b.name || b.id);
    for (let i = 0; i < 12 && used.has(hue); i++) hue = (hue + 37) % 360;
    used.add(hue);
    b.hue = hue;
    b.accent = accentFromHue(hue);
  }
  return bots;
}

function checkReduced() {
  try {
    return window.matchMedia('(prefers-reduced-motion: reduce)').matches;
  } catch (e) {
    return false;
  }
}

/* Elevator-zone test (claude-office queuePositions). */
function useOfficeEvents() {
  const qc = useQueryClient();
  useEffect(() => {
    const offs = [];
    const on = (type, fn) => {
      try {
        const d = host.onEvent(type, fn);
        if (typeof d === 'function') offs.push(d);
      } catch (e) {
        /* events unavailable -> polling still covers us */
      }
    };
    const inv = () => qc.invalidateQueries({ queryKey: ['office'] });
    on('sessions.changed', inv);
    on('message.complete', inv);
    on('tool.start', inv);
    on('gateway.ready', inv);
    return () => {
      for (const d of offs) {
        try {
          d();
        } catch (e) {
          /* ignore */
        }
      }
    };
  }, [qc]);
}

function useNow(intervalMs) {
  const [now, setNow] = useState(() => Date.now());
  useEffect(() => {
    const t = setInterval(() => setNow(Date.now()), intervalMs || 5000);
    return () => clearInterval(t);
  }, [intervalMs]);
  return now;
}

const FALLBACK_LOCALE = (() => {
  try {
    return String((typeof navigator !== 'undefined' && navigator.language) || 'en')
      .toLowerCase()
      .startsWith('id')
      ? 'id'
      : 'en';
  } catch (e) {
    return 'en';
  }
})();

function useOfficeT() {
  const t = usePluginI18n(PLUGIN_ID);
  return useCallback(
    (key, ...args) => {
      const fmt = (s) => String(s).replace(/\{(\d)\}/g, (_, i) => (args[i] != null ? String(args[i]) : ''));
      try {
        const v = t(key);
        if (v && v !== key) return fmt(v);
      } catch (e) {
        /* fall through */
      }
      const loc = I18N[FALLBACK_LOCALE] || I18N.en;
      return fmt(loc[key] != null ? loc[key] : I18N.en[key] != null ? I18N.en[key] : key);
    },
    [t]
  );
}

/* ------------------------------------------------------------------ */
/* Queries                                                             */
/* ------------------------------------------------------------------ */

function useOfficeQueries() {
  const sessionsQ = useQuery({
    queryKey: ['office', 'sessions'],
    queryFn: () => rpc('session.active_list'),
    refetchInterval: POLL_SLOW,
  });
  const sessions = (sessionsQ.data && Array.isArray(sessionsQ.data.sessions) && sessionsQ.data.sessions) || [];
  const storedQ = useQuery({
    queryKey: ['office', 'stored'],
    queryFn: () => rpc('session.list', { limit: 60 }),
    refetchInterval: POLL_SLOW * 3,
  });
  const stored = (storedQ.data && Array.isArray(storedQ.data.sessions) && storedQ.data.sessions) || [];
  const profilesQ = useQuery({
    queryKey: ['office', 'profiles'],
    queryFn: () => rpc('profiles.list', { include_sessions: true }),
    refetchInterval: 10000, /* v4.0: 10s — gentler on the gateway, still snappy for bursts */
  });
  const profiles = (profilesQ.data && Array.isArray(profilesQ.data.profiles) && profilesQ.data.profiles) || [];
  return { sessionsQ, sessions, stored, profilesQ, profiles };
}


