function rawFloorStatus(b, now) {
  /* v4.0 — pure age-of-evidence status (no dead 'status' string: profiles.list
     rows carry no status field — verified against tui_gateway/methods_profiles.py).
     Worker heartbeat wins when fresher than the human session. */
  const age = (t) => (t ? now / 1000 - Number(t) : Infinity);
  const wAge = b.worker ? age(b.worker.last_active) : Infinity;
  const lsAge = b.lastSess ? age(b.lastSess.last_active) : Infinity;
  const freshest = Math.min(wAge, lsAge);
  if (freshest < 60) return 'working';
  if (freshest < 900) return 'idle';
  return 'away';
}

/* v4.0: seconds since the freshest evidence (worker heartbeat or session activity) */
function sttFresh(b, now) {
  const age = (t) => (t ? now / 1000 - Number(t) : Infinity);
  return Math.min(b.worker ? age(b.worker.last_active) : Infinity,
                  b.lastSess ? age(b.lastSess.last_active) : Infinity);
}

function floorStatus(b, now) {
  /* v4.0 honest status: working < 60s (fresh evidence), idle 60s–15m, away > 15m.
     Hysteresis handled by the caller (OfficeTower) so a single stale poll
     cannot flip a floor. */
  return rawFloorStatus(b, now);
}

/* v4.0: pure hysteresis step — a status must be SEEN twice before it is SHOWN.
   Returns the next {shown, seen}; single stale poll can never flip a floor. */
function hystStep(h, raw) {
  if (raw === h.seen) return { shown: raw, seen: raw };
  return { shown: h.shown, seen: raw };
}

/* v4.0: pure burst detector — message_count rose AND evidence fresh (<15m)
   => typing burst until nowMs+12000, else 0 */
function detectBurst(prev, cnt, freshSec, nowMs) {
  return (prev != null && cnt > prev && freshSec < 900) ? nowMs + 12000 : 0;
}

