  const errs = runs.filter((r) => r.status === 'error');
  const lastErr = errs.reduce((m, r) => (!m || (r.ended || r.last || r.started) > (m.ended || m.last || m.started) ? r : m), null);
  const starts = (o.sessions || []).map((s) => s.start || s.last).concat(runs.map((r) => r.started)).filter((x) => x > 0);
  const tools = Object.keys(o.counts || {}).map((k) => [k, o.counts[k]]).filter((e) => e[1] > 0).sort((a, b) => b[1] - a[1] || a[0].localeCompare(b[0]));
